add_action( 'woocommerce_single_product_summary', 'perfectpixel_recent_sales_count', 11 );

function perfectpixel_recent_sales_count() {
	global $product, $wpdb;
	if ( ! $product ) {
		return;
	}
	$days = max( 1, (int) '{{recent_sales_days}}' );
	$key  = 'perfectpixel_recent_sales_' . $product->get_id() . '_' . $days;
	$sold = get_transient( $key );
	if ( false === $sold ) {
		$sold = (int) $wpdb->get_var(
			$wpdb->prepare(
				"SELECT SUM(l.product_qty) FROM {$wpdb->prefix}wc_order_product_lookup l
				INNER JOIN {$wpdb->prefix}wc_order_stats s ON s.order_id = l.order_id
				WHERE l.product_id = %d AND l.date_created >= %s AND s.status IN ('wc-completed','wc-processing')",
				$product->get_id(),
				gmdate( 'Y-m-d H:i:s', time() - $days * DAY_IN_SECONDS )
			)
		);
		set_transient( $key, $sold, HOUR_IN_SECONDS );
	}
	if ( $sold >= max( 1, (int) '{{recent_sales_min}}' ) ) {
		$text = str_replace( array( '{count}', '{days}' ), array( (int) $sold, $days ), '{{recent_sales_text}}' );
		echo '<p class="perfectpixel-recent-sales">' . esc_html( $text ) . '</p>';
	}
}
